import pyomo.environ as pyo

DATA = {
    "DogCapability": 100,
    "TruckCapability": 300,
    "DogCost": 50,
    "TruckCost": 100,
    "MaxBudget": 1000,
    "Modes": ["dog", "truck"],
    # minimum gap so that dogs trips remain strictly fewer than truck trips
    "MinTripGap": 1,
}


def build_model(data=None):
    d = data or DATA
    m = pyo.ConcreteModel()

    m.I = pyo.Set(initialize=d["Modes"])

    capability = {
        "dog": d["DogCapability"],
        "truck": d["TruckCapability"],
    }
    cost = {
        "dog": d["DogCost"],
        "truck": d["TruckCost"],
    }

    m.x = pyo.Var(m.I, within=pyo.NonNegativeIntegers)

    def obj_rule(mm):
        return sum(capability[i] * mm.x[i] for i in mm.I)

    m.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def budget_rule(mm):
        return sum(cost[i] * mm.x[i] for i in mm.I) <= d["MaxBudget"]

    m.budget = pyo.Constraint(rule=budget_rule)

    def dog_less_than_truck_rule(mm):
        return mm.x["dog"] - mm.x["truck"] <= -d["MinTripGap"]

    m.dog_less_than_truck = pyo.Constraint(rule=dog_less_than_truck_rule)

    return m


